CREATE TYPE "UserStatus" AS ENUM ('ACTIVE','DISABLED');
CREATE TYPE "RoleScope" AS ENUM ('GLOBAL','STORE');
CREATE TABLE "Store" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"description" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"deletedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Store_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Store_code_key" ON "Store"("code"); CREATE INDEX "Store_active_idx" ON "Store"("active");
CREATE TABLE "User" ("id" TEXT NOT NULL,"storeId" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"status" "UserStatus" NOT NULL DEFAULT 'ACTIVE',"sessionVersion" INTEGER NOT NULL DEFAULT 0,"deletedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE INDEX "User_storeId_status_idx" ON "User"("storeId","status");
CREATE TABLE "Role" ("id" TEXT NOT NULL,"storeId" TEXT,"name" TEXT NOT NULL,"description" TEXT,"scope" "RoleScope" NOT NULL DEFAULT 'STORE',"system" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Role_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Role_storeId_name_key" ON "Role"("storeId","name"); CREATE INDEX "Role_name_idx" ON "Role"("name");
CREATE TABLE "Permission" ("id" TEXT NOT NULL,"key" TEXT NOT NULL,"description" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Permission_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Permission_key_key" ON "Permission"("key");
CREATE TABLE "UserRole" ("userId" TEXT NOT NULL,"roleId" TEXT NOT NULL,CONSTRAINT "UserRole_pkey" PRIMARY KEY ("userId","roleId")); CREATE INDEX "UserRole_roleId_idx" ON "UserRole"("roleId");
CREATE TABLE "RolePermission" ("roleId" TEXT NOT NULL,"permissionId" TEXT NOT NULL,CONSTRAINT "RolePermission_pkey" PRIMARY KEY ("roleId","permissionId")); CREATE INDEX "RolePermission_permissionId_idx" ON "RolePermission"("permissionId");
CREATE TABLE "Record" ("id" TEXT NOT NULL,"storeId" TEXT NOT NULL,"title" VARCHAR(200) NOT NULL,"description" TEXT,"textValue" TEXT,"numericValue" DECIMAL(18,4),"dateValue" TIMESTAMP(3),"createdById" TEXT NOT NULL,"updatedById" TEXT NOT NULL,"deletedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Record_pkey" PRIMARY KEY ("id")); CREATE INDEX "Record_storeId_createdAt_idx" ON "Record"("storeId","createdAt"); CREATE INDEX "Record_storeId_title_idx" ON "Record"("storeId","title"); CREATE INDEX "Record_storeId_dateValue_idx" ON "Record"("storeId","dateValue");
CREATE TABLE "File" ("id" TEXT NOT NULL,"storeId" TEXT NOT NULL,"recordId" TEXT,"originalName" TEXT NOT NULL,"storageKey" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"uploadedById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"deletedAt" TIMESTAMP(3),CONSTRAINT "File_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "File_storageKey_key" ON "File"("storageKey"); CREATE INDEX "File_storeId_createdAt_idx" ON "File"("storeId","createdAt"); CREATE INDEX "File_storeId_recordId_idx" ON "File"("storeId","recordId");
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"storeId" TEXT,"userId" TEXT,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT,"metadata" JSONB,"ipAddress" TEXT,"userAgent" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id")); CREATE INDEX "AuditLog_storeId_createdAt_idx" ON "AuditLog"("storeId","createdAt"); CREATE INDEX "AuditLog_userId_createdAt_idx" ON "AuditLog"("userId","createdAt"); CREATE INDEX "AuditLog_action_createdAt_idx" ON "AuditLog"("action","createdAt");
CREATE TABLE "PasswordResetToken" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"storeId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PasswordResetToken_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "PasswordResetToken_tokenHash_key" ON "PasswordResetToken"("tokenHash"); CREATE INDEX "PasswordResetToken_userId_expiresAt_idx" ON "PasswordResetToken"("userId","expiresAt");
ALTER TABLE "User" ADD CONSTRAINT "User_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Role" ADD CONSTRAINT "Role_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "UserRole" ADD CONSTRAINT "UserRole_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "UserRole" ADD CONSTRAINT "UserRole_roleId_fkey" FOREIGN KEY ("roleId") REFERENCES "Role"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "RolePermission" ADD CONSTRAINT "RolePermission_roleId_fkey" FOREIGN KEY ("roleId") REFERENCES "Role"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RolePermission" ADD CONSTRAINT "RolePermission_permissionId_fkey" FOREIGN KEY ("permissionId") REFERENCES "Permission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Record" ADD CONSTRAINT "Record_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Record" ADD CONSTRAINT "Record_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Record" ADD CONSTRAINT "Record_updatedById_fkey" FOREIGN KEY ("updatedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "File" ADD CONSTRAINT "File_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "File" ADD CONSTRAINT "File_recordId_fkey" FOREIGN KEY ("recordId") REFERENCES "Record"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "File" ADD CONSTRAINT "File_uploadedById_fkey" FOREIGN KEY ("uploadedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "PasswordResetToken" ADD CONSTRAINT "PasswordResetToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PasswordResetToken" ADD CONSTRAINT "PasswordResetToken_storeId_fkey" FOREIGN KEY ("storeId") REFERENCES "Store"("id") ON DELETE CASCADE ON UPDATE CASCADE;
